(function(root){'use strict';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={receipt:'Written complaint receipt',commenced:'Verified inquiry commencement',firstMeeting:'First Committee meeting',completed:'Inquiry completion',reportSubmitted:'Report provided to employer / District Officer',partiesSupplied:'Report made available to parties',recommendationsReceived:'Actual receipt of recommendations',implemented:'Implementation / action',conciliationRequested:'Woman requested conciliation',settled:'Settlement recorded',settlementForwarded:'Settlement forwarded',settlementCopies:'Settlement copies provided',breachReported:'Settlement breach reported'};
const statusNames={'verification-required':'Verification needed','overdue':'Overdue','due-today':'Due today','alert':'Approaching','scheduled':'Scheduled','completed-late':'Completed late','completed':'Recorded complete','review-recorded':'Review recorded'};
function build(session,result,catalogue=[],context={}){if(session?.format!=='posh-navigator-session'||!session.workflow||!session.timeline||!Array.isArray(result?.items))throw Error('A validated full session is required.');
const timeline=session.timeline,workflow=session.workflow,priority=['overdue','due-today','verification-required','completed-late','alert','scheduled','review-recorded'];
const attention=result.items.filter(x=>x.status!=='completed').map((x,i)=>({...x,originalOrder:i})).sort((a,b)=>(priority.indexOf(a.status)<0?99:priority.indexOf(a.status))-(priority.indexOf(b.status)<0?99:priority.indexOf(b.status))||a.originalOrder-b.originalOrder);
const titles=new Map(catalogue.map(x=>[x.id,x.title]));const documents=[...new Set((timeline.documents||[]).map(x=>x.id))].map(id=>({id,title:titles.get(id)||'Unrecognised template code: '+id}));
const model={context:String(context.kind||'Procedural session'),step:String(context.step||'Verify current step in Navigator'),route:timeline.route==='conciliation'?'Section 10 conciliation':'Sections 11–13 inquiry / report',timelineReady:result.canClose===true,reviewedChoices:Object.keys(workflow.answers||{}).length,historyEntries:(timeline.audit||[]).length,attention,dates:Object.entries(timeline.dates||{}).filter(([,v])=>v).map(([key,value])=>({label:labels[key]||key,value})),documents,generatedAt:String(context.generatedAt||new Date().toISOString()),unsaved:context.unsaved!==false};
model.evidence=session.evidence?.record&&root.NavigatorEvidence?root.NavigatorEvidence.review(session.evidence.record,undefined,timeline.dates||{}):null;return model;}
function fragment(m){const e=escape;return '<h3>Current session at a glance</h3><p><strong>'+e(m.context)+'</strong> · '+e(m.step)+' · '+e(m.route)+'</p><p>'+e(m.reviewedChoices)+' recorded workflow choices · '+e(m.historyEntries)+' timeline history entries · '+e(m.documents.length)+' distinct template draft requests</p><p>'+ (m.timelineReady?'Recorded timeline checks permit completion review. Complete the procedural questions and Committee approvals separately.':'Outstanding timeline checks remain. This sheet does not close the inquiry.')+'</p><p>'+ (m.unsaved?'Current changes still need a verified recovery file. This review sheet cannot restore progress.':'The current session matches its last verified recovery copy. Keep that separate recovery file for resuming.')+'</p><h4>Attention and next actions</h4>'+ (m.attention.length?'<ul>'+m.attention.map(x=>'<li><strong>'+e(statusNames[x.status]||x.status)+': '+e(x.label||x.message)+'</strong>'+(x.due?' · '+e(x.due):'')+'<br>Responsible role: '+e(x.owner||'Committee')+'<br>'+e(x.action||'Verify the applicable next step.')+'</li>').join('')+'</ul>':'<p>No outstanding items are reported by the recorded timeline. Verify the source records and any unrecorded obligations.</p>')+(m.evidence?'<h4>Evidence and annexure review</h4><p>'+e(m.evidence.total)+' recorded references; '+e(m.evidence.pending.length)+' with checks pending.</p>'+(m.evidence.pending.length?'<ul>'+m.evidence.pending.map(x=>'<li>'+e(x.annexure+' — '+x.label)+': '+e(x.gaps.join('; '))+'. '+e(x.owner?'Owner '+x.owner:'Owner to assign')+'; '+e(x.followupDue?'review '+x.followupDue:'review date to assign')+'</li>').join('')+'</ul>':'<p>Verify actual attachments and source records independently.</p>'):'')+'<h4>Recorded milestone dates</h4>'+ (m.dates.length?'<dl>'+m.dates.map(x=>'<dt>'+e(x.label)+'</dt><dd>'+e(x.value)+'</dd>').join('')+'</dl>':'<p>No milestone dates are recorded. No date has been inferred from a document download.</p>')+'<h4>Draft request index</h4><p>These are template-generation requests, not evidence of download completion, signature, issue or service. Retain authorised documents separately.</p>'+ (m.documents.length?'<ul>'+m.documents.map(x=>'<li>'+e(x.title)+' <small>('+e(x.id)+')</small></li>').join('')+'</ul>':'<p>No draft requests are recorded in the timeline.</p>')+'<p class="note">Generated (UTC) '+e(m.generatedAt)+'. This is a local procedural review sheet, not an inquiry report, finding, legal opinion, official audit log or recovery backup. Imported history remains untrusted. Keep participant identities, source records and authorised decisions in institutional custody.</p>';}
function html(m){return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src &#39;none&#39;; style-src &#39;unsafe-inline&#39;; base-uri &#39;none&#39;; form-action &#39;none&#39;"><meta name="referrer" content="no-referrer"><title>Navigator session review sheet</title><style>body{font:16px/1.7 system-ui,sans-serif;color:#11243d;background:#f3f5f8;margin:0}main{max-width:900px;margin:28px auto;padding:28px;background:white;border:1px solid #cbd8e4;border-radius:12px}h1{font-size:30px}h3{font-size:23px}h4{font-size:19px;margin-top:28px}li{margin:14px 0;overflow-wrap:anywhere}dt{font-weight:650}dd{margin:0 0 12px}.note{border-top:1px solid #cbd8e4;padding-top:18px;font-size:14px}p{overflow-wrap:anywhere}@media(max-width:600px){main{margin:8px;padding:18px}}@media print{body{background:white;font-size:11pt}main{margin:0;border:0;padding:0}h3,h4{break-after:avoid}li,dt{break-inside:avoid}}</style></head><body><main><h1>Navigator session review sheet</h1><p>Review outstanding work and retain this sheet under your institution’s custody rules. Use your browser’s Print command if you need a paper copy. No information is sent by this file.</p>'+fragment(m)+'</main></body></html>';}
const api={build,fragment,html};if(typeof module!=='undefined')module.exports=api;else root.NavigatorSessionReview=api;
})(typeof window==='undefined'?globalThis:window);
